#!/usr/bin/env node
//
// Synopsis:
// Test the test runner in the kernel by running it against a predefined set of
// solutions with an expected output.
//
// Output:
// Outputs the diff of the expected test results against the actual test
// results generated by the test runner.
//
// Example:
// ./bin/run-tests-in-container.mjs
//
// The kernel equivalent of
//
//     docker run --entrypoint /opt/test-runner/bin/run-tests.sh <image>
//
// bin/run-tests.sh and tests/ ride in on the tarball; bats comes from the
// sysroot. Nothing about the suite itself changes.

import { report, withContainer } from "./harness.mjs";

const result = await withContainer((container) =>
  container.run(["/opt/test-runner/bin/run-tests.sh"], { cwd: "/opt/test-runner" }),
);

report(result);
